import { COMPONENT_GROUPS, THEME_KEYS, type Spec, type Theme, type ThemeKey, type ProductPattern } from "./spec";

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const kebab = (k: string) => k.replace(/[A-Z0-9]+/g, (m) => "-" + m.toLowerCase());
/** Static templates use the `ds-` prefix; swapped for the brand prefix. Only apply to trusted template text. */
const px = (s: string, p: string) => s.replace(/\bds-/g, `${p}-`);

function readablePastel(color: string, s: Spec) {
  const hex = color.replace("#", "");
  if (!/^[0-9a-f]{6}$/i.test(hex)) return s.dark;
  const rgb = [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255).map((v) => v <= .04045 ? v / 12.92 : ((v + .055) / 1.055) ** 2.4);
  const luminance = (rgb[0] ?? 0) * .2126 + (rgb[1] ?? 0) * .7152 + (rgb[2] ?? 0) * .0722;
  return luminance > .35 ? s.light : s.dark;
}
function pastelVars(t: Theme, s: Spec) {
  return ["pastel1", "pastel2"].map((key) => {
    const theme = readablePastel(t[key as ThemeKey], s);
    return ["fg", "fg2", "bgCard", "bgRaise", "stroke", "accent", "accentFg", "highlight", "highlightFg"].map((k) => `  --ds-${key}-${kebab(k)}: ${theme[k as ThemeKey]};`).join("\n");
  }).join("\n");
}
function themeVars(t: Theme) {
  return THEME_KEYS.map((k: ThemeKey) => `  --ds-${kebab(k)}: ${t[k]};`).join("\n");
}

export function tokensCss(s: Spec) {
  const f = s.fonts, r = s.radius, m = s.motion, u = s.space;
  return px(`/* ${s.brand.name} design tokens. Generated by Promptfolio. */
:root, [data-theme="dark"] {
  color-scheme: dark;
${themeVars(s.dark)}
${pastelVars(s.dark, s)}
}
[data-theme="light"] {
  color-scheme: light;
${themeVars(s.light)}
${pastelVars(s.light, s)}
}
:root {
  --ds-font-display: "${f.display}", ui-sans-serif, system-ui, sans-serif;
  --ds-font-body: "${f.body}", ui-sans-serif, system-ui, sans-serif;
  --ds-font-mono: "${f.mono}", ui-monospace, monospace;
  --ds-radius-sm: ${r.sm}px;
  --ds-radius-md: ${r.md}px;
  --ds-radius-lg: ${r.lg}px;
  --ds-radius-pill: 999px;
  --ds-button-radius: ${s.appearance.buttonRadius}px;
  --ds-control-radius: ${s.appearance.controlRadius}px;
  --ds-check-radius: ${s.appearance.checkRadius}px;
  --ds-border-width: ${s.appearance.borderWidth}px;
  --ds-control-height: ${s.appearance.controlHeight}px;
  --ds-button-height: ${s.appearance.buttonHeight}px;
  --ds-control-size: ${s.appearance.controlSize}px;
  --ds-control-font: ${s.appearance.fontSize}px;
  --ds-control-weight: ${s.appearance.fontWeight};
  --ds-offset: ${s.appearance.shadowOffset}px;
  --ds-tactile-shadow: 0 var(--ds-offset) 0 var(--ds-stroke);
${[1, 2, 3, 4, 6, 8, 12, 16].map((n) => `  --ds-space-${n}: ${n * u}px;`).join("\n")}
  --ds-dur-fast: ${m.fast}ms;
  --ds-dur-base: ${m.base}ms;
  --ds-dur-slow: ${m.slow}ms;
  --ds-ease: ${m.ease};
  --ds-shadow-sm: 0 1px 2px rgba(0,0,0,.12);
  --ds-shadow-md: 0 8px 28px rgba(0,0,0,.18);
}
`, s.brand.prefix);
}

export function tokensJson(s: Spec) {
  return JSON.stringify({ name: s.brand.name, prefix: s.brand.prefix, color: { dark: s.dark, light: s.light }, font: s.fonts, radius: s.radius, spaceUnit: s.space, motion: s.motion, appearance: s.appearance, product: s.product }, null, 2);
}

