function reactFile(s: Spec) {
  return px(`import * as React from "react";
import "../tokens/tokens.css";
import "../dist/__P__.css";

type Div = React.HTMLAttributes<HTMLDivElement>;
const cx = (...c: (string | false | undefined)[]) => c.filter(Boolean).join(" ");

export function Button({ variant = "primary", size = "md", className, ...p }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: "primary" | "highlight" | "secondary" | "ghost" | "danger"; size?: "sm" | "md" | "lg" }) {
  return <button className={cx("ds-btn", "ds-btn--" + variant, size !== "md" && "ds-btn--" + size, className)} {...p} />;
}
export function TextField({ label, hint, error, id, ...p }: React.InputHTMLAttributes<HTMLInputElement> & { label?: string; hint?: string; error?: string }) {
  const generatedId = React.useId(); const fid = id ?? generatedId;
  return <div>{label && <label className="ds-label" htmlFor={fid}>{label}</label>}<input id={fid} className="ds-field" aria-invalid={!!error} {...p} />{(error || hint) && <div className="ds-hint" style={error ? { color: "var(--ds-danger)" } : undefined}>{error ?? hint}</div>}</div>;
}
export function Select({ label, options, id, ...p }: React.SelectHTMLAttributes<HTMLSelectElement> & { label?: string; options: string[] }) {
  const generatedId = React.useId(); const fid = id ?? generatedId;
  return <div>{label && <label className="ds-label" htmlFor={fid}>{label}</label>}<div className="ds-select-wrap"><select id={fid} className="ds-select" {...p}>{options.map((o) => <option key={o}>{o}</option>)}</select><svg className="ds-select-chevron" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m3 6 5 5 5-5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg></div></div>;
}
export function Checkbox({ label, ...p }: React.InputHTMLAttributes<HTMLInputElement> & { label: string }) {
  return <label className="ds-check"><input type="checkbox" {...p} /> {label}</label>;
}
export function Radio({ label, ...p }: React.InputHTMLAttributes<HTMLInputElement> & { label: string }) {
  return <label className="ds-radio"><input type="radio" {...p} /> {label}</label>;
}
export function Switch({ checked, onChange, label }: { checked: boolean; onChange: (v: boolean) => void; label?: string }) {
  return <label style={{ display: "inline-flex", gap: 8, alignItems: "center" }}><button type="button" role="switch" aria-checked={checked} className="ds-switch" onClick={() => onChange(!checked)} />{label}</label>;
}
export function DatePicker({ value, onChange }: { value: Date; onChange: (d: Date) => void }) {
  const [view, setView] = React.useState(new Date(value.getFullYear(), value.getMonth(), 1));
  const first = (view.getDay() + 6) % 7, days = new Date(view.getFullYear(), view.getMonth() + 1, 0).getDate();
  const same = (d: number) => value.getFullYear() === view.getFullYear() && value.getMonth() === view.getMonth() && value.getDate() === d;
  return (
    <div className="ds-cal">
      <div className="ds-cal-head">
        <Button variant="ghost" size="sm" onClick={() => setView(new Date(view.getFullYear(), view.getMonth() - 1, 1))}>‹</Button>
        {view.toLocaleString("en", { month: "long", year: "numeric" })}
        <Button variant="ghost" size="sm" onClick={() => setView(new Date(view.getFullYear(), view.getMonth() + 1, 1))}>›</Button>
      </div>
      <div className="ds-cal-grid">
        {["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"].map((d) => <span key={d}>{d}</span>)}
        {Array.from({ length: first }, (_, i) => <i key={"e" + i} />)}
        {Array.from({ length: days }, (_, i) => <button key={i} aria-selected={same(i + 1)} onClick={() => onChange(new Date(view.getFullYear(), view.getMonth(), i + 1))}>{i + 1}</button>)}
      </div>
    </div>
  );
}
export function SegmentedControl({ options, value, onChange }: { options: string[]; value: string; onChange: (v: string) => void }) {
  return <div className="ds-seg">{options.map((o) => <button key={o} aria-pressed={o === value} onClick={() => onChange(o)}>{o}</button>)}</div>;
}
export function Tabs({ tabs, value, onChange }: { tabs: string[]; value: string; onChange: (v: string) => void }) {
  return <div className="ds-tabs" role="tablist">{tabs.map((t) => <button key={t} role="tab" aria-selected={t === value} onClick={() => onChange(t)}>{t}</button>)}</div>;
}
export function CommandMenu({ items, onSelect }: { items: { label: string; shortcut?: string }[]; onSelect: (label: string) => void }) {
  const [q, setQ] = React.useState(""); const [i, setI] = React.useState(0);
  const list = items.filter((x) => x.label.toLowerCase().includes(q.toLowerCase()));
  return (
    <div className="ds-cmd" onKeyDown={(e) => { if (e.key === "ArrowDown") setI((i + 1) % list.length); if (e.key === "ArrowUp") setI((i - 1 + list.length) % list.length); if (e.key === "Enter" && list[i]) onSelect(list[i].label); }}>
      <input autoFocus placeholder="Type a command or search…" value={q} onChange={(e) => { setQ(e.target.value); setI(0); }} />
      <ul>{list.map((x, n) => <li key={x.label} aria-selected={n === i} onMouseEnter={() => setI(n)} onClick={() => onSelect(x.label)}>{x.label}{x.shortcut && <Kbd>{x.shortcut}</Kbd>}</li>)}</ul>
    </div>
  );
}
export const Pill = ({ active, ...p }: React.ButtonHTMLAttributes<HTMLButtonElement> & { active?: boolean }) => <button className="ds-pill" aria-pressed={!!active} {...p} />;
export const Tag = ({ tone, className, ...p }: React.HTMLAttributes<HTMLSpanElement> & { tone?: "accent" | "ok" | "info" | "danger" }) => <span className={cx("ds-tag", tone && "ds-tag--" + tone, className)} {...p} />;
export const Avatar = ({ initials, size = "md" }: { initials: string; size?: "md" | "lg" }) => <span className={cx("ds-avatar", size === "lg" && "ds-avatar--lg")}>{initials}</span>;
export const Kbd = (p: React.HTMLAttributes<HTMLElement>) => <kbd className="ds-kbd" {...p} />;
export const Card = ({ className, ...p }: Div) => <div className={cx("ds-card", className)} {...p} />;
export function Table({ columns, rows }: { columns: string[]; rows: React.ReactNode[][] }) {
  return <table className="ds-table"><thead><tr>{columns.map((c) => <th key={c}>{c}</th>)}</tr></thead><tbody>{rows.map((r, i) => <tr key={i}>{r.map((c, j) => <td key={j}>{c}</td>)}</tr>)}</tbody></table>;
}
export function Accordion({ items }: { items: { title: string; body: React.ReactNode }[] }) {
  return <div className="ds-acc">{items.map((x) => <details key={x.title}><summary>{x.title}</summary><p>{x.body}</p></details>)}</div>;
}
export type Status = "todo" | "progress" | "done" | "cancelled";
export function StatusIcon({ status }: { status: Status }) {
  const c = { todo: "var(--ds-fg-3)", progress: "var(--ds-warn)", done: "var(--ds-ok)", cancelled: "var(--ds-danger)" }[status];
  return (
    <svg width="14" height="14" viewBox="0 0 14 14" aria-label={status}>
      <circle cx="7" cy="7" r="5.5" fill="none" stroke={c} strokeWidth="1.5" strokeDasharray={status === "todo" ? "2 2" : undefined} />
      {status === "progress" && <path d="M7 7 L7 2.5 A4.5 4.5 0 0 1 11.5 7 Z" fill={c} />}
      {status === "done" && <path d="M4.5 7.2l1.8 1.8 3.4-3.6" stroke={c} strokeWidth="1.5" fill="none" />}
      {status === "cancelled" && <path d="M5 5l4 4M9 5l-4 4" stroke={c} strokeWidth="1.5" />}
    </svg>
  );
}
export function PriorityIcon({ level }: { level: 1 | 2 | 3 }) {
  return <svg width="14" height="14" viewBox="0 0 14 14" aria-label={"priority " + level}>{[0, 1, 2].map((i) => <rect key={i} x={2 + i * 4} y={10 - i * 3} width="2.5" height={3 + i * 3} rx="1" fill={i < level ? "var(--ds-fg)" : "var(--ds-line-strong)"} />)}</svg>;
}
export const ProgressBar = ({ value }: { value: number }) => <div className="ds-progress" role="progressbar" aria-valuenow={value} aria-valuemin={0} aria-valuemax={100}><i style={{ width: Math.min(100, Math.max(0, value)) + "%" }} /></div>;
export function Reveal({ children }: { children: React.ReactNode }) {
  const ref = React.useRef<HTMLDivElement>(null); const [on, setOn] = React.useState(false);
  React.useEffect(() => { const io = new IntersectionObserver(([e]) => e.isIntersecting && setOn(true), { threshold: 0.2 }); if (ref.current) io.observe(ref.current); return () => io.disconnect(); }, []);
  return <div ref={ref} className={cx("ds-reveal", on && "is-in")}>{children}</div>;
}
export const Marquee = ({ items }: { items: string[] }) => <div className="ds-marquee"><div>{[...items, ...items].map((x, i) => <span key={i}>{x}</span>)}</div></div>;
`, s.brand.prefix).replace("__P__", s.brand.prefix);
}

function storiesFile(s: Spec) {
  return `import * as React from "react";
import type { Meta, StoryObj } from "@storybook/react";
import * as C from "./Components";

const meta: Meta = {
  title: "${s.brand.name.replace(/"/g, "")}/Components",
  parameters: { backgrounds: { disable: true } },
  decorators: [(Story, ctx) => { document.documentElement.setAttribute("data-theme", ctx.globals.theme ?? "dark"); return <div className="${s.brand.prefix}-root" style={{ padding: 24 }}><Story /></div>; }],
};
export default meta;
type S = StoryObj;

export const Buttons: S = { render: () => <div style={{ display: "flex", flexWrap: "wrap", gap: 12 }}><C.Button>Primary</C.Button><C.Button variant="secondary">Secondary</C.Button><C.Button variant="ghost">Ghost</C.Button><C.Button variant="danger">Delete</C.Button><C.Button size="sm">Small</C.Button><C.Button size="lg">Large</C.Button></div> };
export const TextField: S = { render: () => <C.TextField label="Project name" placeholder="e.g. Spring launch" hint="Visible to your team." /> };
export const Select: S = { render: () => <C.Select label="Status" options={["Todo", "In progress", "Done"]} /> };
export const Checkbox: S = { render: () => <C.Checkbox label="Email notifications" defaultChecked /> };
export const Radio: S = { render: () => <div style={{ display: "grid", gap: 8 }}><C.Radio name="v" label="Everyone" defaultChecked /><C.Radio name="v" label="Only me" /></div> };
export const Switch: S = { render: () => { const [on, set] = React.useState(true); return <C.Switch checked={on} onChange={set} label="Auto-assign" />; } };
export const DatePicker: S = { render: () => { const [d, set] = React.useState(new Date()); return <C.DatePicker value={d} onChange={set} />; } };
export const SegmentedControl: S = { render: () => { const [v, set] = React.useState("List"); return <C.SegmentedControl options={["List", "Board", "Timeline"]} value={v} onChange={set} />; } };
export const Tabs: S = { render: () => { const [v, set] = React.useState("Overview"); return <C.Tabs tabs={["Overview", "Activity", "Settings"]} value={v} onChange={set} />; } };
export const CommandMenu: S = { render: () => <C.CommandMenu items={[{ label: "Create new item", shortcut: "C" }, { label: "Go to inbox" }, { label: "Switch theme", shortcut: "⌘K" }]} onSelect={() => {}} /> };
export const Pill: S = { render: () => <div style={{ display: "flex", gap: 8 }}><C.Pill active>Active</C.Pill><C.Pill>Backlog</C.Pill></div> };
export const Tag: S = { render: () => <div style={{ display: "flex", gap: 8 }}><C.Tag>Default</C.Tag><C.Tag tone="accent">Accent</C.Tag><C.Tag tone="ok">Success</C.Tag><C.Tag tone="danger">Danger</C.Tag></div> };
export const Avatar: S = { render: () => <C.Avatar initials="KD" size="lg" /> };
export const Kbd: S = { render: () => <C.Kbd>⌘K</C.Kbd> };
export const Card: S = { render: () => <C.Card style={{ maxWidth: 280 }}><C.Tag tone="accent">New</C.Tag><h4>Roadmap</h4><p>A grouped surface for related content.</p></C.Card> };
export const Table: S = { render: () => <C.Table columns={["Name", "Status"]} rows={[["Onboarding", <C.Tag tone="ok">Done</C.Tag>], ["Billing", <C.Tag tone="info">Review</C.Tag>]]} /> };
export const Accordion: S = { render: () => <C.Accordion items={[{ title: "What's included?", body: "Tokens, components and guidelines." }, { title: "Light mode?", body: "Yes." }]} /> };
export const StatusIcon: S = { render: () => <div style={{ display: "flex", gap: 12 }}>{(["todo", "progress", "done", "cancelled"] as const).map((s) => <C.StatusIcon key={s} status={s} />)}</div> };
export const PriorityIcon: S = { render: () => <div style={{ display: "flex", gap: 12 }}><C.PriorityIcon level={1} /><C.PriorityIcon level={2} /><C.PriorityIcon level={3} /></div> };
export const ProgressBar: S = { render: () => <C.ProgressBar value={62} /> };
export const Reveal: S = { render: () => <C.Reveal><C.Card>Fades up on enter</C.Card></C.Reveal> };
export const Marquee: S = { render: () => <C.Marquee items={["Northwind", "Acme", "Globex", "Initech"]} /> };
`;
}

function brandMd(s: Spec) {
  const row = (k: ThemeKey) => `| \`--${s.brand.prefix}-${kebab(k)}\` | ${s.dark[k]} | ${s.light[k]} |`;
  return `# ${s.brand.name}\n\n${s.brand.tagline}\n\n${s.brand.overview}\n\n## Voice\n\n${s.brand.voice}\n\n## Type\n\n- Display: ${s.fonts.display}\n- Body: ${s.fonts.body}\n- Mono: ${s.fonts.mono}\n\n## Colour\n\n| Token | Dark | Light |\n|---|---|---|\n${THEME_KEYS.map(row).join("\n")}\n\n## Shape & motion\n\nRadius ${s.radius.sm}/${s.radius.md}/${s.radius.lg}px · space unit ${s.space}px · durations ${s.motion.fast}/${s.motion.base}/${s.motion.slow}ms · easing \`${s.motion.ease}\`\n`;
}

function componentMd(s: Spec, name: string) {
  const n = s.components.find((c) => c.name === name);
  if (!n) return "";
  const group = COMPONENT_GROUPS.find((g) => g.items.includes(name))?.group ?? "Product patterns";
  return `# ${name}\n\n_${group}_\n\n${n.summary}\n\n${n.usage}\n\n## Do\n\n${n.dos.map((d) => `- ${d}`).join("\n") || "-"}\n\n## Don't\n\n${n.donts.map((d) => `- ${d}`).join("\n") || "-"}\n\n## Code\n\n\`\`\`tsx\nimport { ${name} } from "./react/Components";\n\`\`\`\n\nCSS class: \`.${s.brand.prefix}-${name.toLowerCase()}\` (see \`dist/${s.brand.prefix}.css\`).\n`;
}

function readme(s: Spec) {
  const p = s.brand.prefix;
  return `# ${s.brand.name} design system\n\n${s.brand.tagline}\n\nOpen \`index.html\` in a browser for the full guidelines (dark + light).\n\n## Contents\n\n- \`tokens/tokens.css\`, \`tokens/tokens.json\` — colour (dark + light), type, radius, space, motion\n- \`dist/${p}.css\` — component styles using only tokens\n- \`react/Components.tsx\` — React components\n- \`react/Components.stories.tsx\` — Storybook stories\n- \`guidelines/\` — brand and per-component usage notes\n\n## Use in a project\n\n1. Copy this folder into your repo (e.g. \`src/design-system\`).\n2. Import \`tokens/tokens.css\` and \`dist/${p}.css\` once at your app root.\n3. Set \`data-theme="dark"\` or \`data-theme="light"\` on \`<html>\`.\n4. Import components: \`import { Button } from "./design-system/react/Components";\`\n\n## Storybook\n\nAdd \`"../src/design-system/react/*.stories.tsx"\` to \`stories\` in \`.storybook/main.ts\`. Optionally add a \`theme\` global toolbar (dark/light) — the stories read \`globals.theme\`.\n\n## Fonts\n\n${s.fonts.display}, ${s.fonts.body}, ${s.fonts.mono} — load from Google Fonts.\n`;
}

function productReactFile(s: Spec) {
  return px(`import * as React from "react";
import { Button, Checkbox, ProgressBar } from "./Components";
export const patterns = ${JSON.stringify(s.product.patterns)};
export function ProductPattern({ name }: { name: string }) {
  const x = patterns.find((p) => p.name === name);
  const [running, setRunning] = React.useState(false);
  if (!x) return null;
  return <section className={"ds-pattern ds-pattern--" + x.kind + (running ? " is-breathing" : "")}>
    <h3>{x.title || x.name}</h3>
    {x.kind === "timer" ? <><div className="ds-breath-orbit"/><p>{x.items[0]}</p><Button variant="highlight" aria-pressed={running} onClick={() => setRunning(!running)}>{running ? "Pause session" : "Start session"}</Button></>
      : x.kind === "checklist" ? <div className="ds-pattern-list">{x.items.map((item, i) => <div className="ds-pattern-item" key={item}><Checkbox label={item} defaultChecked={i === 0}/></div>)}</div>
      : <>{x.kind === "progress" && <><div className="ds-pattern-value">3 / 7</div><ProgressBar value={43}/></>}{x.kind === "stat" && <div className="ds-pattern-value">24</div>}{x.items.map((item) => <div key={item} className="ds-pattern-item">{item}</div>)}{x.kind === "plan" && <Button>Choose plan</Button>}</>}
  </section>;
}
`, s.brand.prefix);
}

/** Spec → every file in the package, keyed by relative path. */
export function renderPackage(s: Spec): Record<string, string> {
  const p = s.brand.prefix;
  const files: Record<string, string> = {
    "index.html": guidelinesHtml(s),
    "README.md": readme(s),
    "tokens/tokens.css": tokensCss(s),
    "tokens/tokens.json": tokensJson(s),
    [`dist/${p}.css`]: componentCss(s),
    "react/Components.tsx": reactFile(s),
    "react/Components.stories.tsx": storiesFile(s),
    "guidelines/brand.md": brandMd(s),
  };
  for (const g of COMPONENT_GROUPS) for (const n of g.items) files[`guidelines/components/${n}.md`] = componentMd(s, n);
  if (s.product.patterns.length) {
    files["react/ProductPatterns.tsx"] = productReactFile(s);
    files["react/ProductPatterns.stories.tsx"] = `import * as React from "react";\nimport { ProductPattern, patterns } from "./ProductPatterns";\nexport default { title: ${JSON.stringify(s.brand.name + "/Product patterns")} };\nexport const Examples = { render: () => <div className="${p}-root" style={{display:"grid",gap:24,padding:24}}>{patterns.map((x) => <ProductPattern key={x.name} name={x.name}/>)}</div> };`;
    for (const [i, x] of s.product.patterns.entries()) files[`guidelines/patterns/${i + 1}.md`] = `# ${x.name}\n\n${x.summary}\n\n${x.usage}\n\nImport ProductPattern from react/ProductPatterns and pass name=${JSON.stringify(x.name)}.`;
    files["guidelines/product.md"] = `# Product context\n\n${s.product.purpose}\n\n## Pages & workflows\n${s.product.pages.map((x) => `- ${x}`).join("\n")}`;
  }
  return files;
}
